Here is the root cause:
The btintel_hw_error() function issues synchronous HCI commands (__hci_cmd_sync) without holding the hci_req_sync_lock, allowing a race with btintel_shutdown_combined() (called from hci_dev_do_close) that holds the same lock. This leads to concurrent manipulation of hdev->req_status/req_rsp, causing a use-after-free when the close path frees the response skb while the error path still accesses it.

Here is the patch:

 void btintel_hw_error(struct hci_dev *hdev, u8 code)
 {
 	struct sk_buff *skb;
 	u8 type = 0x00;

 	bt_dev_err(hdev, "Hardware error 0x%2.2x", code);

+	hci_req_sync_lock(hdev);
+
 	skb = __hci_cmd_sync(hdev, HCI_OP_RESET, 0, NULL, HCI_INIT_TIMEOUT);
 	if (IS_ERR(skb)) {
 		bt_dev_err(hdev, "Reset after hardware error failed (%ld)",
 			   PTR_ERR(skb));
-		return;
+		goto unlock;
 	}
 	kfree_skb(skb);

 	skb = __hci_cmd_sync(hdev, 0xfc22, 1, &type, HCI_INIT_TIMEOUT);
 	if (IS_ERR(skb)) {
 		bt_dev_err(hdev, "Retrieving Intel exception info failed (%ld)",
 			   PTR_ERR(skb));
-		return;
+		goto unlock;
 	}

 	if (skb->len != 13) {
 		bt_dev_err(hdev, "Exception info size mismatch");
 		kfree_skb(skb);
-		return;
+		goto unlock;
 	}

 	bt_dev_err(hdev, "Exception info %s", (char *)(skb->data + 1));

 	kfree_skb(skb);
+
+unlock:
+	hci_req_sync_unlock(hdev);
 }
 EXPORT_SYMBOL_GPL(btintel_hw_error);


